#!/usr/bin/env python3
"""Generate docs/FOUNDER-CONTROL-CENTER.md from canonical company data in docs/company/data/ (workstreams, stages, hypotheses, validation ladder, capital gates,
risks, roadmap) plus the readiness scores read from docs/readiness/VALIDATION-SCOREBOARD.md. Invents nothing; a blocked workstream is reported as blocked.
  python3 tools/founder_center.py            write the file       python3 tools/founder_center.py --check    exit 1 if stale"""
import csv, os, re, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def p(*a): return os.path.join(R, *a)
def rows(f): return list(csv.DictReader(open(p("docs/company/data", f), encoding="utf-8")))
def cell(s, n=140):
    s = (s or "").replace("|", "/").replace("\n", " ").strip()
    return s if len(s) <= n else s[: n - 1].rsplit(" ", 1)[0] + "..."
sb = open(p("docs/readiness/VALIDATION-SCOREBOARD.md"), encoding="utf-8").read()
m = re.search(r"\*\*Total \(of 95\)\*\* \| \*\*(\d+) = (\d+)%\*\* \| \*\*(\d+) = (\d+)%\*\*", sb)
design, evidence = (m.group(1), m.group(3)) if m else ("?", "?")
ws, stages, hyp, lad, cap, risks, road = (rows(f) for f in ("workstreams.csv", "stages.csv", "hypotheses.csv", "validation-ladder.csv", "capital-gates.csv", "risks.csv", "roadmap.csv"))
blocked = [w for w in ws if w["status"].startswith("BLOCKED")]
L = ["# NASHA founder control center (generated by tools/founder_center.py; do not hand-edit)", "",
     f"**Readiness (from the scoreboard, unchanged by this page):** evidence {evidence}/95, design {design}/95. Nothing has been cooked, brewed, tasted, quoted, legally reviewed or tested with customers. Everything below is planning unless a row says otherwise; **digital progress is never physical evidence.**", "",
     "**Two lanes.** Lane A needs the real world (cooking, brewing, tasting, customers, quotes, professionals). Lane B is autonomous digital work. A blocked Lane A item does not stop Lane B. Blockers are reported per workstream, not for the whole company.", "",
     f"**Top alert (D-78):** an Austin restaurant named Nasha was found by T1 searches: the name carries HIGH CONFLICT RISK until an IP attorney reviews it. `docs/decisions/DECISIONS.md` D-78; `brand/TRADEMARK-SCREENING.md`.", "",
     "## Where NASHA is today", ""]
cur = [s for s in stages if s["today_status"] == "CURRENT"]
L += [f"**Current stage: {cur[0]['stage_id']} {cur[0]['name']}.** " + cell(cur[0]["today_note"], 260) if cur else "Current stage: not set.", "",
      "| Stage | Name | Today | Capital exposure |", "|---|---|---|---|"]
L += [f"| {s['stage_id']} | {cell(s['name'], 70)} | {s['today_status']} | {s['capital_exposure_class']} |" for s in stages]
L += ["", "Entry, exit, evidence and go/hold/kill questions per stage: `docs/company/data/stages.csv`.", "", "## Workstreams", "",
      f"{len([w for w in ws if w['status'].startswith('ACTIVE')])} active, {len(blocked)} blocked on external input. Detail (what we know/don't know, decision unlocked, owner, evidence level): `docs/company/data/workstreams.csv`.", "",
      "| Workstream | Status | Current blocker | Next digital action | Next real-world action | Pri |", "|---|---|---|---|---|---|"]
for w in sorted(ws, key=lambda x: (int(x["priority"] or 9), x["workstream"])):
    L.append(f"| **{w['workstream']}** | {w['status']} | {cell(w['current_blocker'], 90)} | {cell(w['next_digital_action'], 110)} | {cell(w['next_real_world_action'], 110)} | {w['priority']} |")
L += ["", "## North-star hypotheses (test order; all UNTESTED)", "", "| Rank | Id | Hypothesis | Importance | Uncertainty | Cost to test | Earliest test |", "|---|---|---|---|---|---|---|"]
for h in sorted(hyp, key=lambda x: int(x["rank"])):
    L.append(f"| {h['rank']} | {h['id']} | {cell(h['hypothesis'], 80)} | {h['importance_1to5']} | {h['uncertainty_1to5']} | {h['cost_to_test']} | {cell(h['earliest_test'], 90)} |")
L += ["", "## Validation ladder (cheapest learning first; steps may be skipped)", "", "| Step | Question answered | Cost | Speed | Reversibility | Lane | Unlocks |", "|---|---|---|---|---|---|---|"]
for s in lad: L.append(f"| {s['step_id']} {cell(s['step'], 50)} | {cell(s['question_answered'], 90)} | {s['relative_cost']} | {s['relative_speed']} | {s['reversibility']} | {s['lane']} | {cell(s['decision_unlocked'], 70)} |")
L += ["", "## Capital allocation: do not spend flagship money to answer a small question", "", "| Spend category | Prove first | Cheaper test first | Failure that saves the spend |", "|---|---|---|---|"]
for c in cap: L.append(f"| {c['category']} | {cell(c['must_be_proven_before_spending'], 100)} | {cell(c['cheaper_test_first'], 100)} | {cell(c['failure_that_saves_us_the_spend'], 90)} |")
L += ["", "## Top risks", "", "| # | Risk | Reduced by | Lane |", "|---|---|---|---|"]
for r in risks: L.append(f"| {r['rank']} | {cell(r['risk'], 110)} | {cell(r['what reduces it'], 110)} | {r['lane']} |")
L += ["", "## Next 100 days (dependency-driven, no calendar dates)", "", "| Phase | Digital (lane B) | Founder | Professional | Physical (lane A) | Exit signal |", "|---|---|---|---|---|---|"]
for r in road: L.append(f"| **{r['phase']}** | {cell(r['digital_work (lane B)'], 100)} | {cell(r['founder_work'], 90)} | {cell(r['professional_work'], 90)} | {cell(r['physical_work (lane A)'], 80)} | {cell(r['exit_signal'], 70)} |")
L += ["", "## Where to look", "",
      "- Products: `docs/CORE5-CONTROL-CENTER.md` (ten products), `docs/PROTOTYPE-READINESS.md`, `docs/company/CORE5-COMMERCIAL-LOGIC.md`, `docs/company/BEER-AND-NA-BUSINESS-SYSTEM.md`, `docs/company/FOOD-FAILURE-CONTINGENCIES.md`.",
      "- Cook now: `food/t1-test-sheets/14-SESSION-1-FOUNDER-MODE.md`.",
      "- Real-world asks: `docs/EXTERNAL-INPUT-QUEUE.md`, `docs/company/PROFESSIONAL-REVIEW-PIPELINE.md`, `docs/company/OUTREACH-DRAFTS.md` (drafts, not sent).",
      "- Customers: `research/customer-discovery/FIRST-30-LEARNING-PLAN.md`, `TASTING-FEEDBACK-FORM.md`, `CODING-SYSTEM.md`.",
      "- Market and site: `docs/company/AUSTIN-MARKET-MAP.md`, `docs/company/data/site-scorecard.csv`. Operations: `docs/company/OPERATING-DAY-MODEL.md`, `docs/company/STAFFING-ARCHITECTURE.md`, `docs/company/data/supply-spec.csv`.",
      "- Legal and IP: `docs/company/REGULATORY-QUESTION-TREE.md`, `ip/IP-ASSET-TRACKER.csv`. Money: `docs/MVP-AND-INVESTOR-READINESS.md`, `ops/finance/` (scenario fields; every value blank). Brand: `docs/company/BRAND-EXPERIENCE-AND-RESPONSIBLE-ALCOHOL.md`. Decisions: `docs/decisions/decision-register.csv` (`python3 tools/decision_register.py check`).", ""]
out = "\n".join(L)
path = p("docs/FOUNDER-CONTROL-CENTER.md")
if "--check" in sys.argv: sys.exit(0 if os.path.exists(path) and open(path, encoding="utf-8").read() == out else 1)
open(path, "w", encoding="utf-8").write(out); print("wrote docs/FOUNDER-CONTROL-CENTER.md")
